// Post-processes the Drizzle schema generated by the Better Auth CLI so every
// timestamp column is `timestamptz` (project rule: store timestamps in UTC).
import { readFileSync, writeFileSync } from "node:fs";

const file = process.argv[2] ?? "db/schema/auth.ts";
const source = readFileSync(file, "utf8");

const patched = source.replace(
  /timestamp\("([a-z_]+)"\)/g,
  'timestamp("$1", { withTimezone: true })',
);

const header =
  "// Generated by `npm run auth:generate` (Better Auth CLI + scripts/patch-auth-schema.mjs).\n// Do not edit by hand.\n";

writeFileSync(file, patched.startsWith("// Generated") ? patched : header + patched);
console.log(`Patched timestamps to timestamptz in ${file}`);
